<?php declare(strict_types=1);

namespace App\UI\Web\Image;

use App\Database\EntityManagerDecorator;
use App\Model\Entity\UserEntity;
use App\Model\Service\UserAvatarService;
use App\Settings\ImagesDir;
use Nette\Application\Responses\FileResponse;
use Nette\Application\UI\Presenter;

/**
 * Sends a thumbnail of contributte/imagist (the files are outside www/, route cache/<scope>/_<filter>/<name>, the links
 * are generated by n:img). Public - the avatars are shown with the posts of a public topic too - but only the avatar
 * of an EXISTING user, only the thumbnails made on upload (never generated here), never sniffed by the browser.
 */
class ImagePresenter extends Presenter
{
    public function __construct(
        private readonly EntityManagerDecorator $em,
        private readonly ImagesDir $imagesDir,
    ) {
        parent::__construct();
    }

    public function actionDefault(string $scope, string $filter, string $name) : void
    {
        // the route allows only these values; checked again, the path below is made of them
        if ($scope !== UserAvatarService::SCOPE
            || !in_array($filter, UserAvatarService::FILTERS, true)
            || preg_match('#^[a-zA-Z0-9]{32}\.webp$#D', $name) !== 1
        ) {
            $this->error('Image was not found.');
        }

        $user = $this->em->getRepository(UserEntity::class)->findOneBy(['avatar' => $scope . '/' . $name]);

        if ($user === null) {
            $this->error('Image was not found.');
        }

        $path = rtrim((string) $this->imagesDir->get(), '/') . '/cache/' . $scope . '/_' . $filter . '/' . $name;

        if (!is_file($path)) {
            $this->error('Image was not found.');
        }

        $response = $this->getHttpResponse();
        $response->setHeader('X-Content-Type-Options', 'nosniff');
        // a new avatar gets a new random name, so the old address may be cached
        $response->setHeader('Cache-Control', 'public, max-age=86400');
        $this->sendResponse(new FileResponse($path, $name, 'image/webp', forceDownload: false));
    }
}
